namespace core = "urn:eigenius:core";
namespace patent = "urn:eigenius:demo:patent";
namespace completion = "urn:eigenius:program:components:completion";
namespace request = "urn:eigenius:program:request";

// --- Input type ---

class patent:PatentClaim {
    description = "A patent claim or abstract to be analyzed.";
    requires patent:title, patent:patent_number, patent:abstract_text;
    recommends patent:assignee, patent:filing_date;
}

property patent:title : core:string {
    description = "Title of the patent.";
}

property patent:abstract_text : core:string {
    description = "The abstract or claim text of the patent.";
}

// --- Structured analysis ---

class patent:PatentAnalysis {
    description = "Structured analysis extracted from a patent claim.";
    requires patent:invention_category, patent:technical_domain,
             patent:key_innovations, patent:practical_applications;
}

property patent:key_innovations : core:value_array {
    description = "List of key innovations or novel aspects claimed.";
    element_type = core:string;
}

// --- Pipeline ---

program patent:analyze_patent : patent:PatentClaim -> patent:PatentBrief {
    let analysis : patent:PatentAnalysis = CompleteJson(input) {
        completion:user_prompt = "Analyze this patent and extract structured information.";
        completion:output_schema = patent:PatentAnalysis;
    };
    let summary : core:string = CompleteText(analysis) {
        completion:user_prompt = "Summarise for a non-specialist.";
    };
    Construct patent:PatentBrief {
        patent:summary = summary,
        patent:analysis = analysis
    }
}

// Phase 4 SDK usage: load the patent resource, run the analysis,
// inspect the resulting brief.

import { Eigenius } from "@eigenius/client";

const client = new Eigenius({ baseUrl: "http://localhost:8787" });

// 1. Load the input resource into the active layer.
const patent = await client.resources.load(
  "./demo/patent/transformer-patent.json",
);

// 2. Run the analyze_patent program against the loaded resource.
const brief = await client.programs.run(
  "urn:eigenius:demo:patent:analyze_patent",
  { input: patent.id },
);

// 3. Render the structured brief as a notebook table.
console.log("Summary:\n", brief["urn:eigenius:demo:patent:summary"]);

const analysis = brief["urn:eigenius:demo:patent:analysis"];
console.table({
  category:    analysis["urn:eigenius:demo:patent:invention_category"],
  domain:      analysis["urn:eigenius:demo:patent:technical_domain"],
  innovations: analysis["urn:eigenius:demo:patent:key_innovations"].length,
});
